  s.explored.push(s.location);
  s.knowledge++;
  s.inventory.ore += type === "mine" ? 6 + professionBonus(s, "Miner") * 2 : 2;
  s.inventory.wood += type === "forest" ? 5 : 1;
  s.inventory.herbs +=
    type === "forest" ? 4 + professionBonus(s, "Herbalist") * 2 : 1;
