    pixel(c, x - 12, y - 4, 25, 15, "#594b35");
    pixel(c, x - 11, y - 5, 23, 12, "#9c7547");
    pixel(c, x - 11, y - 7, 23, 5, "#c1a06a");
    pixel(c, x - 8, y - 7, 2, 17, "#e0c48b");
    pixel(c, x + 7, y - 7, 2, 17, "#e0c48b");
    pixel(c, x - 1, y - 3, 4, 5, "#dbc176");
